289	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
290	     * one more than the number of owners already in that city.
291	     */
292	    private String generateCustomerCode(Owner owner) {
293	        String cityPrefix = prefix3(owner.getCity());
294	        String lastNamePrefix = prefix3(owner.getLastName());
295	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
296	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
297	    }
