/**
 * Fills the presentation-only {@code membershipLevel}, the numeric level assigned to the
 * owner on creation: it starts at 1, gains 1 when an email is present, gains 1 when
 * namesakeCount is 0, and is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved
 * for tenure).
 */
@AfterMapping
default void addMembershipLevel(Owner owner, @MappingTarget OwnerDto ownerDto) {
    ownerDto.setMembershipLevel(membershipLevel(owner));
}

/**
 * Computes an owner's numeric membership level: starts at 1, adds 1 when an email is present,
 * adds 1 when namesakeCount is 0, and caps the result at {@value #MAX_MEMBERSHIP_LEVEL}
 * (level 4 is reserved for tenure).
 */
static int membershipLevel(Owner owner) {
    int level = 1;
    if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
        level++;
    }
    if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
        level++;
    }
    return Math.min(level, MAX_MEMBERSHIP_LEVEL);
}

